insert into public.products (id, slug, name, category, price, compare_at, short_desc, description, images, stock, active, featured, source_url) values
  ('p27415', 'rosemary-water-200-ml-shampoo-100-ml', 'Rosemary water (200 ml) + (Shampoo 100 ml)', 'combos', 442.5, 531.0, 'Multipurpose hair and skin mist that strengthens roots, reduces hair fall, and improves scalp health.', 'Long Description Ananta Beauty Rosemary Water Spray is a refreshing and multi-purpose hair and skin mist designed to promote healthier, stronger, and more vibrant hair. Enriched with natural botanical extracts and essential nutrients, this lightweight formula works directly on the scalp to improve hair growth, reduce hair fall, and enhance overall hair quality. Infused with the goodness of rosemary extract and rosemary oil, this spray helps stimulate blood circulation in the scalp, awakening dormant hair follicles and encouraging natural hair regrowth. The presence of nourishing ingredients like glycerin and vitamin E helps lock in moisture, keeping your scalp hydrated and preventing dryness, frizz, and breakage. This advanced formula also contains powerful herbal extracts such as amla, brahmi, and mulethi, which are known for strengthening hair from the roots, improving thickness, and adding natural shine. Eucalyptus oil and thyme oil help soothe scalp irritation, reduce dandruff, and maintain a clean, healthy scalp environment. Unlike heavy oils or sticky serums, this rosemary water spray is non-greasy and fast-absorbing, making it ideal for daily use. It can be used as a leave-in treatment for hair or as a refreshing mist for skin, providing instant hydration and revitalization throughout the day. With regular use, hair appears stronger, smoother, and visibly healthier, whil', '["/img/p27415_1.jpg", "/img/p27415_2.jpg"]'::jsonb, 40, true, true, 'https://anantabeauty.in/product/rosemary-water-200-ml-shampoo-100-ml/'),
  ('p27411', 'haircarecombo-serum-rosemary-onion-shampoo', 'Super saver Hair Growth Combo: Serum + Rosemary Water Spray + Onion Shampoo (330 ml)', 'combos', 643.1, 649.0, 'Multipurpose hair and skin mist that strengthens roots, reduces hair fall , and improves scalp health.', 'Long Description Ananta Beauty Rosemary Water Spray is a refreshing and multi-purpose hair and skin mist designed to promote healthier, stronger, and more vibrant hair. Enriched with natural botanical extracts and essential nutrients, this lightweight formula works directly on the scalp to improve hair growth, reduce hair fall, and enhance overall hair quality. Infused with the goodness of rosemary extract and rosemary oil, this spray helps stimulate blood circulation in the scalp, awakening dormant hair follicles and encouraging natural hair regrowth. The presence of nourishing ingredients like glycerin and vitamin E helps lock in moisture, keeping your scalp hydrated and preventing dryness, frizz, and breakage. This advanced formula also contains powerful herbal extracts such as amla, brahmi, and mulethi, which are known for strengthening hair from the roots, improving thickness, and adding natural shine. Eucalyptus oil and thyme oil help soothe scalp irritation, reduce dandruff, and maintain a clean, healthy scalp environment. Unlike heavy oils or sticky serums, this rosemary water spray is non-greasy and fast-absorbing, making it ideal for daily use. It can be used as a leave-in treatment for hair or as a refreshing mist for skin, providing instant hydration and revitalization throughout the day. With regular use, hair appears stronger, smoother, and visibly healthier, whil', '["/img/p27411_1.jpg", "/img/p27411_2.jpg"]'::jsonb, 40, true, true, 'https://anantabeauty.in/product/haircarecombo-serum-rosemary-onion-shampoo/'),
  ('p27408', 'rosemary-water-spray-for-hair-growth-pack-of-1-200-ml-copy-anti-hair-loss-hair-growth-serum-30ml', 'Rosemary Water Spray for Hair Growth – Pack of 1 (200 ml) + Anti-Hair Loss Hair Growth Serum – 30ml', 'combos', 587.64, 649.0, 'Multipurpose hair and skin mist that strengthens roots, reduces hair fall, and improves scalp health.', 'Long Description Ananta Beauty Rosemary Water Spray is a refreshing and multi-purpose hair and skin mist designed to promote healthier, stronger, and more vibrant hair. Enriched with natural botanical extracts and essential nutrients, this lightweight formula works directly on the scalp to improve hair growth, reduce hair fall, and enhance overall hair quality. Infused with the goodness of rosemary extract and rosemary oil, this spray helps stimulate blood circulation in the scalp, awakening dormant hair follicles and encouraging natural hair regrowth. The presence of nourishing ingredients like glycerin and vitamin E helps lock in moisture, keeping your scalp hydrated and preventing dryness, frizz, and breakage. This advanced formula also contains powerful herbal extracts such as amla, brahmi, and mulethi, which are known for strengthening hair from the roots, improving thickness, and adding natural shine. Eucalyptus oil and thyme oil help soothe scalp irritation, reduce dandruff, and maintain a clean, healthy scalp environment. Unlike heavy oils or sticky serums, this rosemary water spray is non-greasy and fast-absorbing, making it ideal for daily use. It can be used as a leave-in treatment for hair or as a refreshing mist for skin, providing instant hydration and revitalization throughout the day. With regular use, hair appears stronger, smoother, and visibly healthier, whil', '["/img/p27408_1.jpg", "/img/p27408_2.jpg"]'::jsonb, 40, true, false, 'https://anantabeauty.in/product/rosemary-water-spray-for-hair-growth-pack-of-1-200-ml-copy-anti-hair-loss-hair-growth-serum-30ml/'),
  ('p27403', 'keratin-onion-black-seed-shampoo-400-ml', 'Keratin Red Onion & Black Seed Shampoo – (Pack of 4 x 100 ml)', 'shampoos', 472.0, 587.64, 'Hair strengthening shampoo enriched with keratin, red onion, and black seed shampoo that helps reduce hair fall, improve hair texture, and promote healthy hair growth. Free from sulphates and parabens. Suitable for all hair types.', 'Ananta Beauty Keratin+Red Onion & Black Seed Shampoo is a powerful hair care solution formulated to reduce hair fall, strengthen weak hair, and improve overall hair health. Enriched with natural extracts and keratin, this shampoo deeply nourishes the scalp while repairing damaged hair strands. The gentle cleansing formula effectively removes dirt and excess oil without stripping natural moisture, making it ideal for regular use. It helps restore shine, smoothness, and strength to your hair. Key Benefits: Helps reduce hair fall and breakage Promotes healthy hair growth Strengthens hair from root to tip Improves hair smoothness and shine Provides scalp hydration and nourishment Key Ingredients: Keratin: Repairs damaged hair and smoothens hair texture Red Onion Extract: Boosts blood circulation and supports hair growth Black Seed: Nourishes roots and helps prevent hair breakage How to Use: Apply to wet hair and massage gently into the scalp to form a lather. Rinse thoroughly with water. Repeat if required. Use regularly for best results. Additional Information: No sulphates No parabens No mineral oil Suitable for all hair types Suitable for men and women', '["/img/p27403_1.jpg", "/img/p27403_2.jpg", "/img/p27403_3.jpg"]'::jsonb, 40, true, true, 'https://anantabeauty.in/product/keratin-onion-black-seed-shampoo-400-ml/'),
  ('p27400', 'rosemary-water-spray-for-hair-growth-pack-of-1-200-ml', 'Rosemary Water Spray for Hair Growth – Pack of 1 (200 ml)', 'sprays', 234.82, 283.2, 'Multipurpose hair and skin mist that strengthens roots, reduces hair fall, and improves scalp health.', 'Long Description Ananta Beauty Rosemary Water Spray is a refreshing and multi-purpose hair and skin mist designed to promote healthier, stronger, and more vibrant hair. Enriched with natural botanical extracts and essential nutrients, this lightweight formula works directly on the scalp to improve hair growth, reduce hair fall, and enhance overall hair quality. Infused with the goodness of rosemary extract and rosemary oil, this spray helps stimulate blood circulation in the scalp, awakening dormant hair follicles and encouraging natural hair regrowth. The presence of nourishing ingredients like glycerin and vitamin E helps lock in moisture, keeping your scalp hydrated and preventing dryness, frizz, and breakage. This advanced formula also contains powerful herbal extracts such as amla, brahmi, and mulethi, which are known for strengthening hair from the roots, improving thickness, and adding natural shine. Eucalyptus oil and thyme oil help soothe scalp irritation, reduce dandruff, and maintain a clean, healthy scalp environment. Unlike heavy oils or sticky serums, this rosemary water spray is non-greasy and fast-absorbing, making it ideal for daily use. It can be used as a leave-in treatment for hair or as a refreshing mist for skin, providing instant hydration and revitalization throughout the day. With regular use, hair appears stronger, smoother, and visibly healthier, whil', '["/img/p27400_1.jpg", "/img/p27400_2.jpg"]'::jsonb, 40, true, false, 'https://anantabeauty.in/product/rosemary-water-spray-for-hair-growth-pack-of-1-200-ml/'),
  ('p27397', 'anti-hair-loss-hair-growth-serum-pack-of-3-90-ml-copy', 'Anti-Hair Loss Hair Growth Serum – Pack of 3 (90 ml )', 'serums', 1001.82, 1062.0, 'Powerful anti-hair loss serum enriched with Redensyl, Anagain, Procapil & Follicusan to stimulate hair growth, strengthen roots, and reduce hair fall. Suitable for men & women for thicker, healthier hair.', 'Ananta Beauty Anti-Hair Loss Serum is a scientifically formulated solution designed to reduce hair fall and promote healthy hair regrowth. This lightweight and non-greasy serum works at the root level to nourish the scalp, strengthen hair follicles, and improve overall hair density. Regular use helps revive inactive hair follicles, making hair stronger, thicker, and healthier over time. Key Benefits: Stimulates natural hair growth Reduces hair fall and thinning Strengthens weak and damaged hair Promotes thicker and fuller hair Improves scalp health Key Ingredients: Redensyl (3%): Helps activate dormant hair follicles and supports new hair growth Anagain (4%): Encourages hair growth and prolongs the growth phase Procapil (1%): Strengthens hair roots and reduces hair loss Follicusan (3%): Nourishes the scalp and supports healthy hair growth Rice Water Extract: Enhances hair strength and shine How to Use: Apply a few drops directly onto the scalp and gently massage in circular motions. Leave it on for at least 6–8 hours or overnight. Use daily for best results. Additional Information: Paraben-free and sulphate-free Suitable for all hair types Non-greasy and lightweight formula Suitable for both men and women', '["/img/p27397_1.jpg", "/img/p27397_2.jpg"]'::jsonb, 40, true, false, 'https://anantabeauty.in/product/anti-hair-loss-hair-growth-serum-pack-of-3-90-ml-copy/'),
